+package ext
+
+import (
+	"context"
+	"encoding/json"
+	"fmt"
+	"io"
+
+	flipt "github.com/markphelps/flipt/rpc/flipt"
+	"github.com/markphelps/flipt/storage"
+	"gopkg.in/yaml.v2"
+)
+
+type lister interface {
+	ListFlags(context.Context, ...storage.QueryOption) ([]*flipt.Flag, error)
+	ListRules(context.Context, string, ...storage.QueryOption) ([]*flipt.Rule, error)
+	ListSegments(context.Context, ...storage.QueryOption) ([]*flipt.Segment, error)
+}
+
+type Exporter struct {
+	store     lister
+	batchSize uint64
+}
+
+func NewExporter(store lister) *Exporter { return &Exporter{store: store, batchSize: 25} }
+
+func (e *Exporter) Export(ctx context.Context, w io.Writer) error {
+	doc := &Document{}
+	for offset := uint64(0); ; offset += e.batchSize {
+		flags, err := e.store.ListFlags(ctx, storage.WithOffset(offset), storage.WithLimit(e.batchSize))
+		if err != nil {
+			return fmt.Errorf("getting flags: %w", err)
+		}
+		for _, f := range flags {
+			out := &Flag{Key: f.Key, Name: f.Name, Description: f.Description, Enabled: f.Enabled}
+			keys := make(map[string]string, len(f.Variants))
+			for _, v := range f.Variants {
+				var attachment interface{}
+				if v.Attachment != "" {
+					if err := json.Unmarshal([]byte(v.Attachment), &attachment); err != nil {
+						return fmt.Errorf("decoding attachment for variant %q: %w", v.Key, err)
+					}
+				}
+				out.Variants = append(out.Variants, &Variant{Key: v.Key, Name: v.Name, Description: v.Description, Attachment: attachment})
+				keys[v.Id] = v.Key
+			}
+			rules, err := e.store.ListRules(ctx, f.Key)
+			if err != nil {
+				return fmt.Errorf("getting rules for flag %q: %w", f.Key, err)
+			}
+			for _, r := range rules {
+				rule := &Rule{SegmentKey: r.SegmentKey, Rank: uint(r.Rank)}
+				for _, d := range r.Distributions {
+					rule.Distributions = append(rule.Distributions, &Distribution{VariantKey: keys[d.VariantId], Rollout: d.Rollout})
+				}
+				out.Rules = append(out.Rules, rule)
+			}
+			doc.Flags = append(doc.Flags, out)
+		}
+		if uint64(len(flags)) < e.batchSize {
+			break
+		}
+	}
+	for offset := uint64(0); ; offset += e.batchSize {
+		segments, err := e.store.ListSegments(ctx, storage.WithOffset(offset), storage.WithLimit(e.batchSize))
+		if err != nil {
+			return fmt.Errorf("getting segments: %w", err)
+		}
+		for _, s := range segments {
+			out := &Segment{Key: s.Key, Name: s.Name, Description: s.Description}
+			for _, c := range s.Constraints {
+				out.Constraints = append(out.Constraints, &Constraint{Type: c.Type.String(), Property: c.Property, Operator: c.Operator, Value: c.Value})
+			}
+			doc.Segments = append(doc.Segments, out)
+		}
+		if uint64(len(segments)) < e.batchSize {
+			break
+		}
+	}
+	enc := yaml.NewEncoder(w)
+	defer enc.Close()
+	return enc.Encode(doc)
+}
