@@ -0,0 +1,136 @@
+package ext
+
+import (
+	"context"
+	"encoding/json"
+	"fmt"
+	"io"
+	"reflect"
+
+	flipt "github.com/markphelps/flipt/rpc/flipt"
+	"gopkg.in/yaml.v2"
+)
+
+type creator interface {
+	CreateFlag(context.Context, *flipt.CreateFlagRequest) (*flipt.Flag, error)
+	CreateVariant(context.Context, *flipt.CreateVariantRequest) (*flipt.Variant, error)
+	CreateSegment(context.Context, *flipt.CreateSegmentRequest) (*flipt.Segment, error)
+	CreateConstraint(context.Context, *flipt.CreateConstraintRequest) (*flipt.Constraint, error)
+	CreateRule(context.Context, *flipt.CreateRuleRequest) (*flipt.Rule, error)
+	CreateDistribution(context.Context, *flipt.CreateDistributionRequest) (*flipt.Distribution, error)
+}
+
+type Importer struct{ store creator }
+
+func NewImporter(store creator) *Importer { return &Importer{store: store} }
+
+func (i *Importer) Import(ctx context.Context, r io.Reader) error {
+	doc := new(Document)
+	if err := yaml.NewDecoder(r).Decode(doc); err != nil {
+		return fmt.Errorf("decoding document: %w", err)
+	}
+	variants := make(map[string]*flipt.Variant)
+	for _, f := range doc.Flags {
+		if _, err := i.store.CreateFlag(ctx, &flipt.CreateFlagRequest{Key: f.Key, Name: f.Name, Description: f.Description, Enabled: f.Enabled}); err != nil {
+			return fmt.Errorf("importing flag %q: %w", f.Key, err)
+		}
+		for _, v := range f.Variants {
+			var attachment string
+			if v.Attachment != nil {
+				normalized, err := convert(v.Attachment)
+				if err != nil {
+					return fmt.Errorf("normalizing attachment for variant %q: %w", v.Key, err)
+				}
+				b, err := json.Marshal(normalized)
+				if err != nil {
+					return fmt.Errorf("encoding attachment for variant %q: %w", v.Key, err)
+				}
+				attachment = string(b)
+			}
+			created, err := i.store.CreateVariant(ctx, &flipt.CreateVariantRequest{FlagKey: f.Key, Key: v.Key, Name: v.Name, Description: v.Description, Attachment: attachment})
+			if err != nil {
+				return fmt.Errorf("importing variant %q: %w", v.Key, err)
+			}
+			variants[f.Key+":"+v.Key] = created
+		}
+	}
+	for _, s := range doc.Segments {
+		if _, err := i.store.CreateSegment(ctx, &flipt.CreateSegmentRequest{Key: s.Key, Name: s.Name, Description: s.Description}); err != nil {
+			return fmt.Errorf("importing segment %q: %w", s.Key, err)
+		}
+		for _, c := range s.Constraints {
+			typ, ok := flipt.ComparisonType_value[c.Type]
+			if !ok {
+				return fmt.Errorf("unknown constraint type %q", c.Type)
+			}
+			if _, err := i.store.CreateConstraint(ctx, &flipt.CreateConstraintRequest{SegmentKey: s.Key, Type: flipt.ComparisonType(typ), Property: c.Property, Operator: c.Operator, Value: c.Value}); err != nil {
+				return fmt.Errorf("importing constraint: %w", err)
+			}
+		}
+	}
+	for _, f := range doc.Flags {
+		for _, r := range f.Rules {
+			rule, err := i.store.CreateRule(ctx, &flipt.CreateRuleRequest{FlagKey: f.Key, SegmentKey: r.SegmentKey, Rank: int32(r.Rank)})
+			if err != nil {
+				return fmt.Errorf("importing rule: %w", err)
+			}
+			for _, d := range r.Distributions {
+				v, ok := variants[f.Key+":"+d.VariantKey]
+				if !ok {
+					return fmt.Errorf("variant %q not found for flag %q", d.VariantKey, f.Key)
+				}
+				if _, err := i.store.CreateDistribution(ctx, &flipt.CreateDistributionRequest{FlagKey: f.Key, RuleId: rule.Id, VariantId: v.Id, Rollout: d.Rollout}); err != nil {
+					return fmt.Errorf("importing distribution: %w", err)
+				}
+			}
+		}
+	}
+	return nil
+}
+
+// convert recursively replaces non-string map keys with their string form.
+func convert(value interface{}) (interface{}, error) {
+	switch v := value.(type) {
+	case map[interface{}]interface{}:
+		out := make(map[string]interface{}, len(v))
+		for key, item := range v {
+			out[fmt.Sprint(key)] = item
+		}
+		return convert(out)
+	case map[string]interface{}:
+		out := make(map[string]interface{}, len(v))
+		for key, item := range v {
+			converted, err := convert(item)
+			if err != nil {
+				return nil, err
+			}
+			out[key] = converted
+		}
+		return out, nil
+	case []interface{}:
+		out := make([]interface{}, len(v))
+		for n, item := range v {
+			converted, err := convert(item)
+			if err != nil {
+				return nil, err
+			}
+			out[n] = converted
+		}
+		return out, nil
+	default:
+		rv := reflect.ValueOf(value)
+		if rv.IsValid() && rv.Kind() == reflect.Map {
+			out := make(map[string]interface{}, rv.Len())
+			iter := rv.MapRange()
+			for iter.Next() {
+				converted, err := convert(iter.Value().Interface())
+				if err != nil {
+					return nil, err
+				}
+				out[fmt.Sprint(iter.Key().Interface())] = converted
+			}
+			return out, nil
+		}
+		return value, nil
+	}
+}
